/**
 * Orders, Payments and Transaction Search through @paypal/paypal-server-sdk (generated by APIMatic).
 * Disputes and webhooks are not in the SDK, so those use plain REST (lib/paypal/http.ts) with
 * the same credentials.
 *
 * Every SDK call is wrapped by sdkCall() so it shows up in the Under the hood drawer with its
 * PayPal-Debug-Id, just like the REST calls.
 */
import { randomUUID } from "node:crypto";
import {
  ApiError,
  CheckoutPaymentIntent,
  Client,
  Environment,
  ItemCategory,
  OrdersController,
  PaymentsController,
  PaypalExperienceUserAction,
  PaypalWalletContextShippingPreference,
  ShipmentCarrier,
  TransactionSearchController,
  type ApiResponse,
  type CapturedPayment,
  type Order,
  type OrderRequest,
  type SearchResponse,
} from "@paypal/paypal-server-sdk";
import { assertSandbox, env } from "@/lib/env";
import { PayPalError } from "./http";
import { record } from "@/lib/replay/recorder";
import { currentMode, recordCall } from "./log";

let client: Client | null = null;

/** Built once and kept: the SDK caches its own OAuth token on the client. */
function sdk(): Client {
  assertSandbox();
  if (!client) {
    client = new Client({
      clientCredentialsAuthCredentials: {
        oAuthClientId: env.paypalClientId,
        oAuthClientSecret: env.paypalClientSecret,
      },
      environment: Environment.Sandbox,
      timeout: 45_000,
    });
  }
  return client;
}

async function sdkCall<T>(
  meta: { method: string; path: string; feature?: string; requestId?: string },
  run: () => Promise<ApiResponse<T>>,
): Promise<{ result: T; raw: any; debugId: string | null }> {
  if (currentMode() === "replay") {
    const { replayRequest } = await import("@/lib/replay/engine");
    const res = await replayRequest<any>({ method: meta.method as "GET", path: meta.path, feature: meta.feature });
    return { result: res.data as T, raw: res.data, debugId: res.debugId };
  }
  const started = Date.now();
  try {
    const res = await run();
    const debugId = res.headers?.["paypal-debug-id"] ?? null;
    recordCall({
      method: meta.method,
      path: meta.path,
      status: res.statusCode,
      debugId,
      ms: Date.now() - started,
      via: "sdk",
      feature: meta.feature,
      requestId: meta.requestId,
    });
    let raw: any = null;
    try {
      raw = typeof res.body === "string" ? JSON.parse(res.body) : null;
    } catch {
      raw = null;
    }
    record({ kind: "sdk", method: meta.method, path: meta.path, status: res.statusCode, debugId, ms: Date.now() - started, response: res.result });
    return { result: res.result, raw, debugId };
  } catch (err) {
    if (err instanceof ApiError) {
      const body = (err.result ?? {}) as { name?: string; message?: string; debug_id?: string; details?: { issue?: string; description?: string }[] };
      const debugId = err.headers?.["paypal-debug-id"] ?? body.debug_id ?? null;
      recordCall({
        method: meta.method,
        path: meta.path,
        status: err.statusCode,
        debugId,
        ms: Date.now() - started,
        via: "sdk",
        feature: meta.feature,
        requestId: meta.requestId,
      });
      throw new PayPalError({
        status: err.statusCode,
        code: body.name ?? "PAYPAL_ERROR",
        message: [body.message, body.details?.[0]?.issue, body.details?.[0]?.description].filter(Boolean).join(" | ") || err.message,
        debugId,
        issue: body.details?.[0]?.issue ?? null,
        details: body.details,
      });
    }
    recordCall({ method: meta.method, path: meta.path, status: 0, debugId: null, ms: Date.now() - started, via: "sdk", feature: meta.feature });
    throw new PayPalError({
      status: 0,
      code: "NO_RESPONSE",
      message: `No response from PayPal (${err instanceof Error ? err.message : "network error"}).`,
      unknownOutcome: meta.method !== "GET",
    });
  }
}

export type StoreOrderInput = {
  invoiceId: string;
  customId: string;
  description: string;
  items: { name: string; sku: string; quantity: number; unitPrice: string; description?: string }[];
  shippingAmount?: string;
  shipTo?: {
    fullName: string;
    addressLine1: string;
    addressLine2?: string;
    city: string;
    state: string;
    postalCode: string;
    countryCode: string;
  };
  returnUrl: string;
  cancelUrl: string;
  requestId?: string;
  feature?: string;
};

const usd = (value: string) => ({ currencyCode: "USD", value });

export function orderTotal(input: Pick<StoreOrderInput, "items" | "shippingAmount">): string {
  const items = input.items.reduce((sum, i) => sum + Math.round(Number(i.unitPrice) * 100) * i.quantity, 0);
  const shipping = Math.round(Number(input.shippingAmount ?? "0") * 100);
  return ((items + shipping) / 100).toFixed(2);
}

/** POST /v2/checkout/orders. The buyer approves with their PayPal account, then we capture. */
export async function createStoreOrder(input: StoreOrderInput) {
  const itemTotal = (
    input.items.reduce((sum, i) => sum + Math.round(Number(i.unitPrice) * 100) * i.quantity, 0) / 100
  ).toFixed(2);
  const body: OrderRequest = {
    intent: CheckoutPaymentIntent.Capture,
    purchaseUnits: [
      {
        referenceId: input.invoiceId,
        invoiceId: input.invoiceId,
        customId: input.customId,
        description: input.description.slice(0, 127),
        amount: {
          currencyCode: "USD",
          value: orderTotal(input),
          breakdown: {
            itemTotal: usd(itemTotal),
            ...(input.shippingAmount ? { shipping: usd(input.shippingAmount) } : {}),
          },
        },
        items: input.items.map((i) => ({
          name: i.name.slice(0, 127),
          sku: i.sku,
          quantity: String(i.quantity),
          unitAmount: usd(i.unitPrice),
          description: i.description?.slice(0, 127),
          category: ItemCategory.PhysicalGoods,
        })),
        ...(input.shipTo
          ? {
              shipping: {
                name: { fullName: input.shipTo.fullName },
                address: {
                  addressLine1: input.shipTo.addressLine1,
                  addressLine2: input.shipTo.addressLine2,
                  adminArea2: input.shipTo.city,
                  adminArea1: input.shipTo.state,
                  postalCode: input.shipTo.postalCode,
                  countryCode: input.shipTo.countryCode,
                },
              },
            }
          : {}),
      },
    ],
    paymentSource: {
      paypal: {
        experienceContext: {
          brandName: "Juniper & Moss",
          userAction: PaypalExperienceUserAction.PayNow,
          shippingPreference: input.shipTo
            ? PaypalWalletContextShippingPreference.SetProvidedAddress
            : PaypalWalletContextShippingPreference.GetFromFile,
          returnUrl: input.returnUrl,
          cancelUrl: input.cancelUrl,
        },
      },
    },
  };
  const requestId = input.requestId ?? randomUUID();
  const orders = new OrdersController(sdk());
  const { result, raw } = await sdkCall<Order>(
    { method: "POST", path: "/v2/checkout/orders", feature: input.feature ?? "Store: create order", requestId },
    () => orders.createOrder({ body, paypalRequestId: requestId, prefer: "return=representation" }),
  );
  const approveUrl = result.links?.find((l) => l.rel === "payer-action" || l.rel === "approve")?.href ?? null;
  return { id: result.id!, status: result.status, approveUrl, raw };
}

/** POST /v2/checkout/orders/{id}/capture */
export async function captureStoreOrder(orderId: string, opts: { requestId?: string; feature?: string } = {}) {
  const requestId = opts.requestId ?? randomUUID();
  const orders = new OrdersController(sdk());
  const { result, raw } = await sdkCall<Order>(
    { method: "POST", path: `/v2/checkout/orders/${orderId}/capture`, feature: opts.feature ?? "Store: capture order", requestId },
    () => orders.captureOrder({ id: orderId, paypalRequestId: requestId, prefer: "return=representation" }),
  );
  const capture = result.purchaseUnits?.[0]?.payments?.captures?.[0];
  return { status: result.status, captureId: capture?.id ?? null, captureStatus: capture?.status ?? null, raw };
}

/** GET /v2/checkout/orders/{id} */
export async function getOrder(orderId: string, feature = "Case file: read order") {
  const orders = new OrdersController(sdk());
  const { result, raw } = await sdkCall<Order>(
    { method: "GET", path: `/v2/checkout/orders/${orderId}`, feature },
    () => orders.getOrder({ id: orderId }),
  );
  return { order: result, raw };
}

/** POST /v2/checkout/orders/{id}/track. Tracking added at fulfillment is the best dispute evidence. */
export async function addOrderTracking(
  orderId: string,
  input: { captureId: string; trackingNumber: string; carrierNameOther: string; notifyPayer?: boolean },
  feature = "Store: add tracking",
) {
  const orders = new OrdersController(sdk());
  const { result, raw } = await sdkCall<Order>(
    { method: "POST", path: `/v2/checkout/orders/${orderId}/track`, feature },
    () =>
      orders.createOrderTracking({
        id: orderId,
        body: {
          captureId: input.captureId,
          trackingNumber: input.trackingNumber,
          // Fictional carriers only: PayPal's carrier list is real brands, so we file as OTHER.
          carrier: ShipmentCarrier.Other,
          carrierNameOther: input.carrierNameOther,
          notifyPayer: input.notifyPayer ?? false,
        },
      }),
  );
  return { order: result, raw };
}

/** GET /v2/payments/captures/{id} */
export async function getCapture(captureId: string, feature = "Case file: read capture") {
  const payments = new PaymentsController(sdk());
  const { result, raw } = await sdkCall<CapturedPayment>(
    { method: "GET", path: `/v2/payments/captures/${captureId}`, feature },
    () => payments.getCapturedPayment({ captureId }),
  );
  return { capture: result, raw };
}

/**
 * GET /v1/reporting/transactions. Sandbox transaction search lags by up to about three hours,
 * so callers treat an empty result as "not indexed yet", never as "no such transaction".
 */
export async function searchTransaction(transactionId: string, aroundIso: string, feature = "Case file: transaction details") {
  const around = new Date(aroundIso).getTime();
  const iso = (ms: number) => new Date(ms).toISOString().replace(/\.\d{3}Z$/, "Z");
  const search = new TransactionSearchController(sdk());
  const { result, raw } = await sdkCall<SearchResponse>(
    { method: "GET", path: `/v1/reporting/transactions?transaction_id=${transactionId}&fields=all`, feature },
    () =>
      search.searchTransactions({
        startDate: iso(around - 2 * 24 * 3600 * 1000),
        endDate: iso(Math.min(Date.now(), around + 2 * 24 * 3600 * 1000)),
        transactionId,
        fields: "all",
        pageSize: 10,
      }),
  );
  return { result, raw };
}
